local function notify(t, txt)
    local n = Instance.new('TextLabel')
    n.Size = UDim2.new(0, 300, 0, 40)
    n.Position = UDim2.new(0.5, -150, 0, 20)
    n.BackgroundColor3 = Color3.fromRGB(20, 20, 30)
    n.TextColor3 = Color3.fromRGB(0, 220, 255)
    n.Font = Enum.Font.GothamBold
    n.Text = '⚡ '..t..': '..txt
    n.Parent = CoreGui
    Instance.new('UICorner', n).CornerRadius = UDim.new(0, 8)
    task.delay(3, function() n:Destroy() end)
end
