-- Tab Creator Function
local function createTab(name, index)
    local btn = Instance.new("TextButton")
    btn.Size = UDim2.new(0.33, -4, 1, 0)
    btn.BackgroundColor3 = index == 1 and Color3.fromRGB(0, 220, 255) or Color3.fromRGB(26, 26, 40)
    btn.TextColor3 = index == 1 and Color3.fromRGB(0, 0, 0) or Color3.new(1, 1, 1)
    btn.Text = name
    btn.Font = Enum.Font.GothamBold
    btn.TextSize = 11
    btn.Parent = Tabs
    Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 6)
    
    local frame = Instance.new("ScrollingFrame")
    frame.Size = UDim2.new(1, 0, 1, 0)
    frame.BackgroundTransparency = 1
    frame.ScrollBarThickness = 4
    frame.Visible = index == 1
    frame.Parent = TabContent
    Instance.new("UIListLayout", frame).Padding = UDim.new(0, 5)
    
    btn.MouseButton1Click:Connect(function()
        for _, v in pairs(Tabs:GetChildren()) do
            if v:IsA("TextButton") then
                v.BackgroundColor3 = Color3.fromRGB(26, 26, 40)
                v.TextColor3 = Color3.new(1, 1, 1)
            end
        end
        for _, v in pairs(TabContent:GetChildren()) do
            if v:IsA("ScrollingFrame") then v.Visible = false end
        end
        btn.BackgroundColor3 = Color3.fromRGB(0, 220, 255)
        btn.TextColor3 = Color3.new(0, 0, 0)
        frame.Visible = true
    end)
    
    return frame
end

local FarmTab = createTab("🌾 Farm", 1)
local ShopTab = createTab("🛒 Shop", 2)
local TpTab = createTab("📍 Teleports", 3)

