local isFarming = false
local FarmBtn = Instance.new("TextButton")
FarmBtn.Size = UDim2.new(1, 0, 0, 35)
FarmBtn.BackgroundColor3 = Color3.fromRGB(0, 200, 100)
FarmBtn.Text = "🌾 Toggle Auto Quest & Farm"
FarmBtn.Font = Enum.Font.GothamBold
FarmBtn.Parent = FarmTab
Instance.new("UICorner", FarmBtn).CornerRadius = UDim.new(0, 6)

FarmBtn.MouseButton1Click:Connect(function()
    isFarming = not isFarming
    FarmBtn.BackgroundColor3 = isFarming and Color3.fromRGB(200, 50, 50) or Color3.fromRGB(0, 200, 100)
    FarmBtn.Text = isFarming and "🛑 Stop Farming" or "🌾 Toggle Auto Quest & Farm"
end)

-- The Smart Quest Loop
RunService.Heartbeat:Connect(function()
    if not isFarming or not getRoot() then return end
    
    local playerLevel = LocalPlayer.Data and LocalPlayer.Data.Level and LocalPlayer.Data.Level.Value or 0
    local activeQuest = nil
    
    -- Find the correct quest from DB based on level
    for _, q in ipairs(DB.Quests) do
        if playerLevel >= q.minLevel and playerLevel <= q.maxLevel then
            activeQuest = q
            break
        end
    end
    
    if activeQuest then
        local questGui = LocalPlayer.PlayerGui.Main:FindFirstChild("Quest")
        if not questGui or not questGui.Visible then
            pcall(function()
                CommF_:InvokeServer("StartQuest", activeQuest.questName, 1)
            end)
        else
            local nearest, dist = nil, 150
            for _, obj in ipairs(workspace:GetDescendants()) do
                if obj:IsA("Model") and obj:FindFirstChild("Humanoid") and obj:FindFirstChild("HumanoidRootPart") then
                    if obj.Humanoid.Health > 0 and string.find(obj.Name, activeQuest.mob) then
                        local d = (getRoot().Position - obj.HumanoidRootPart.Position).Magnitude
                        if d < dist then dist = d; nearest = obj end
                    end
                end
            end
            if nearest then
                getRoot().CFrame = nearest.HumanoidRootPart.CFrame * CFrame.new(0, 25, 0)
                VirtualUser:CaptureController()
                VirtualUser:Button1Down(Vector2.new(1280, 672), workspace.CurrentCamera.CFrame)
            end
        end
    end
end)

