local function updateList(filter)
    TpList:ClearAllChildren()
    local count = 0
    for name, cframe in pairs(DB.Islands) do
        if filter == '' or string.find(string.lower(name), string.lower(filter)) then
            local btn = Instance.new('TextButton')
            btn.Size = UDim2.new(1, 0, 0, 30)
            btn.BackgroundColor3 = Color3.fromRGB(26, 26, 40)
            btn.TextColor3 = Color3.new(1,1,1)
            btn.Text = '📍 ' .. name
            btn.Parent = TpList
            Instance.new('UICorner', btn).CornerRadius = UDim.new(0, 6)
            btn.MouseButton1Click:Connect(function()
                if getRoot() then TweenService:Create(getRoot(), TweenInfo.new(0.5), {CFrame = cframe}):Play() end
            end)
            count = count + 1
            if count >= 50 then break end
        end
    end
end
SearchBox:GetPropertyChangedSignal('Text'):Connect(function() updateList(SearchBox.Text) end)
updateList('')

